export const Promise: Story = {
  parameters: {
    docs: {
      description: { story: "Use `toast.promise` to update one supplementary toast as an asynchronous task moves through loading, success, and error states. Keep pending state and recovery in the control or surface that owns the task. For uploads, imports, and exports, preserve progress, results, and failures in a persistent activity surface; the toast is not job history." },
      source: { code: PromiseSource },
    },
  },
  render: PromiseExample,
};

export const Action: Story = {
  parameters: {
    docs: {
      description: { story: "Pass button props with `actionProps` to render a supplementary action. Keep the same action available in a persistent surface after the toast disappears. An Undo toast must not be the only way to restore an item; provide recovery in the affected list or history.

The example below shows the action API and closes the toast. A real Undo handler must also restore the application state.

```tsx
const id = toast.add({
  id: "event-created",
  title: "Event created",
  actionProps: {
    children: "Undo",
    onClick() {
      toast.close(id);
    },
  },
});
```" },
      source: { code: ActionSource },
    },
  },
  render: ActionExample,
};

export const Progress: Story = {
  parameters: {
    docs: {
      description: { story: "Use the ID returned by `toast.add` to update a specific toast. Call `toast.close(id)` to dismiss it.

This example demonstrates updates to a supplementary notification. Long-running work needs persistent progress and recovery in an activity surface, even if its toast stays open." },
      source: { code: ProgressSource },
    },
  },
  render: ProgressExample,
};

export const Queue: Story = {
  parameters: {
    docs: {
      description: { story: "This example adds five notifications with automatic dismissal disabled to demonstrate the stack. Hover or focus the stack to see and scroll the full queue.

A queue is not notification history. Avoid one toast per rapid or bulk operation; update the affected interface and keep any useful summary in a persistent surface." },
      source: { code: QueueSource },
    },
  },
  render: QueueExample,
};

